package app.streamnest;
import android.app.*;import android.content.*;import android.os.*;import java.util.*;import org.json.*;
final class TrailerRegression {
 static Bundle run(Instrumentation test)throws Exception{Context c=test.getTargetContext();WatchSync.pending=true;WatchSync.testPairingCode="";Trailers.Fetcher original=Trailers.fetcher;MainActivity[] main={null};TitleScreen[] dialog={null};String[] opened={null};
 Instrumentation.ActivityMonitor monitor=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent intent){if(Intent.ACTION_VIEW.equals(intent.getAction())&&intent.getData()!=null&&"www.youtube.com".equals(intent.getData().getHost())){opened[0]=intent.getDataString();return new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};test.addMonitor(monitor);
 try{Trailers.cache.clear();Trailers.fetcher=(url,deadline)->{if(url.contains("cinemeta")){String id=url.substring(url.lastIndexOf('/')+1).replace(".json","");return new JSONObject().put("meta",new JSONObject().put("id",id).put("trailers",new JSONArray().put(new JSONObject().put("type","Trailer").put("source","xEQP4VVuyrY"))));}return new JSONObject().put("provider_name","YouTube").put("title","Fixture trailer");};HomeLibrary.cached=new ArrayList<>();HomeLibrary.cachedAt=System.currentTimeMillis();main[0]=(MainActivity)test.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Thread.sleep(500);String before=WatchProgress.records(c).toString();TorrentEngine engine=StreamService.engine;
 int index=0;for(String kind:new String[]{"movies","shows","animes"}){Catalog.Title t=Catalog.parse(new JSONObject().put("imdb","tt"+(99004000+index++)).put("title","Trailer fixture"),kind);test.runOnMainSync(()->{dialog[0]=new TitleScreen(main[0],t);dialog[0].show();});for(int n=0;n<100&&dialog[0].trailerResult==null;n++)Thread.sleep(50);test.waitForIdleSync();Thread.sleep(500);android.graphics.Bitmap screenshot=test.getUiAutomation().takeScreenshot();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(c.getCacheDir(),"trailer-"+kind+".png"))){screenshot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}screenshot.recycle();test.runOnMainSync(()->{HomeRegression.check(dialog[0].trailerResult!=null&&dialog[0].trailer.isShown(),"Trailer button missing");HomeRegression.check(dialog[0].trailer.isFocusable(),"Trailer is not remote-focusable");dialog[0].trailer.performClick();});HomeRegression.check("https://www.youtube.com/watch?v=xEQP4VVuyrY".equals(opened[0]),"Wrong trailer handoff");opened[0]=null;test.runOnMainSync(()->dialog[0].dismiss());}
 HomeRegression.check(before.equals(WatchProgress.records(c).toString()),"Trailer changed viewing progress");HomeRegression.check(engine==StreamService.engine,"Trailer started torrent engine");Trailers.fetcher=original;Trailers.cache.clear();int live=0;for(String[] item:new String[][]{{"tt2380307","movies"},{"tt11280740","shows"},{"tt7441658","animes"}}){Catalog.Title t=Catalog.parse(new JSONObject().put("imdb",item[0]).put("title","Live trailer"),item[1]);HomeRegression.check(Trailers.resolve(t)!=null,"Live trailer lookup unavailable for "+item[0]);live++;}Bundle b=new Bundle();b.putString("result","PASS: native movie/series/anime Trailer buttons, keyboard focus, intercepted YouTube launch, no torrent/progress changes; live lookup count "+live);return b;
 }finally{Trailers.fetcher=original;Trailers.cache.clear();test.removeMonitor(monitor);if(dialog[0]!=null)test.runOnMainSync(()->dialog[0].dismiss());if(main[0]!=null)test.runOnMainSync(()->main[0].finish());WatchSync.pending=false;WatchSync.testPairingCode=null;HomeLibrary.clear();}}
}
